<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('quotes.view');$pageTitle='Cotizaciones';$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$currency=(string)($_GET['currency']??'');$where=[];$params=[];if($q!==''){$where[]='(q.quotation_number LIKE ? OR c.company_name LIKE ? OR q.recipient_name LIKE ? OR q.recipient_email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if(in_array($status,['draft','sent','accepted','rejected','expired'],true)){$where[]='q.status=?';$params[]=$status;}if(in_array($currency,['CLP','USD','BRL'],true)){$where[]='q.currency=?';$params[]=$currency;}$sql='SELECT q.*,c.company_name,c.country,u.name creator_name FROM quotations q JOIN clients c ON c.id=q.client_id LEFT JOIN users u ON u.id=q.created_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY q.issue_date DESC,q.id DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$quotes=$stmt->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Historial de cotizaciones</h2><span class="table-sub"><?=count($quotes)?> registros encontrados · CLP, USD y BRL · Español, Português e English</span></div><?php if(has_permission('quotes.create')):?><a class="btn btn-primary" href="quotation_form.php">+ NUEVA COTIZACIÓN</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters"><input name="q" value="<?=e($q)?>" placeholder="Número, cliente o email"><select name="status"><option value="">Todos los estados</option><?php foreach(['draft','sent','accepted','rejected','expired']as$st):?><option value="<?=$st?>" <?=$status===$st?'selected':''?>><?=e(quote_status_label($st))?></option><?php endforeach;?></select><select name="currency"><option value="">Todas las monedas</option><option value="CLP" <?=$currency==='CLP'?'selected':''?>>Pesos chilenos</option><option value="USD" <?=$currency==='USD'?'selected':''?>>Dólares</option><option value="BRL" <?=$currency==='BRL'?'selected':''?>>Reales</option></select><button class="btn btn-secondary btn-small">Filtrar</button></form></div><div class="table-wrap"><?php if(!$quotes):?><div class="empty">Todavía no hay cotizaciones.<?php if(has_permission('quotes.create')):?> <a href="quotation_form.php">Crea la primera</a>.<?php endif;?></div><?php else:?><table class="data-table"><thead><tr><th>Número / cliente</th><th>País</th><th>Fecha</th><th>Idioma</th><th>Moneda</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($quotes as$qrow):?><tr><td><a class="table-title" href="quotation_view.php?id=<?=(int)$qrow['id']?>"><?=e($qrow['quotation_number'])?></a><span class="table-sub"><?=e($qrow['company_name'])?></span></td><td><?=e($qrow['country']?:'Sin país')?></td><td><?=e(format_date($qrow['issue_date']))?><span class="table-sub">Válida: <?=e(format_date($qrow['valid_until']))?></span></td><td><?=e(language_label($qrow['language']))?></td><td><?=e($qrow['currency'])?></td><td><strong><?=e(format_money($qrow['total'],$qrow['currency']))?></strong></td><td><span class="badge badge-<?=e(quote_status_class($qrow['status']))?>"><?=e(quote_status_label($qrow['status']))?></span></td><td><div class="actions"><a class="btn btn-light btn-small" href="quotation_view.php?id=<?=(int)$qrow['id']?>">Ver</a><?php if(has_permission('quotes.edit')):?><a class="btn btn-light btn-small" href="quotation_form.php?id=<?=(int)$qrow['id']?>">Editar</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
